fn snap_all_day_to_midnight(dt: &str) -> String {
    let Some((date, time)) = dt.split_once('T') else {
        return dt.to_string();
    };
    let hour: u32 = time.get(0..2).and_then(|h| h.parse().ok()).unwrap_or(0);
    if hour >= 12 {
        format!("{}T00:00:00", next_calendar_day(date))
    } else {
        format!("{date}T00:00:00")
    }
}
